{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Autoradiography in rats showed that the compound entered brain parenchyma via the BBB, directly supporting meaningful CNS access after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Biodistribution in mice showed the compound penetrated the BBB intact, with brain uptake of 0.17–0.25% dose/g over 5–30 min, supporting meaningful brain exposure despite a low brain-to-blood ratio.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "In rats, CSF concentration was only 4.5 µg/mL versus 195 µg/mL in serum after i.p. administration, indicating low brain availability and arguing against meaningful CNS access for that compound.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most transferred direct in-vivo records support meaningful CNS access after systemic administration, including BBB autoradiography, brain biodistribution, PET/SPECT uptake, and CSF equilibration. One direct CSF record indicates low brain availability, but the overall evidence preponderance supports a pass.",
  "evidence_gaps": [
    "Assay-transfer scores are moderate (~0.6), limiting certainty in cross-molecule applicability.",
    "One transferred record reports low CSF availability, so the positive direction is not unanimous.",
    "Several positive records lack detailed dose-response or time-course data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

